  // Give Chart.js a tiny bit of time to paint.
  await page.waitForTimeout(250);

  // Screenshot full page (single chart + title/legend).
  await page.screenshot({ path: outPath, fullPage: true });

  await browser.close();
  console.log('Wrote', outPath);
})();
